// Helper Functions
// ═══════════════════════════════════════════════════════════════════

/**
 * Returns summary statistics for the extended capabilities (501-1000).
 */
export function getExtendedStats() {
  const total = OPENCLAW_EXTENDED.length;
  const implemented = OPENCLAW_EXTENDED.filter(c => c.status === "implemented").length;
  const partial = OPENCLAW_EXTENDED.filter(c => c.status === "partial").length;
  const stub = OPENCLAW_EXTENDED.filter(c => c.status === "stub").length;
  const missing = OPENCLAW_EXTENDED.filter(c => c.status === "missing").length;
  const byCategory = {} as Record<OpenClawExtendedCategory, { total: number; implemented: number; partial: number; stub: number; missing: number }>;
  for (const c of OPENCLAW_EXTENDED) {
    if (!byCategory[c.category]) byCategory[c.category] = { total: 0, implemented: 0, partial: 0, stub: 0, missing: 0 };
    byCategory[c.category].total++;
    byCategory[c.category][c.status]++;
  }
  return { total, implemented, partial, stub, missing, byCategory };
}

/**
 * Look up a single extended capability by its ID (501-1000).
 */
export function getExtendedCapabilityById(id: number): OpenClawExtendedCapability | undefined {
  return OPENCLAW_EXTENDED.find(c => c.id === id);
}

/**
 * Return all extended capabilities in a given category.
 */
export function getExtendedCapabilitiesByCategory(category: OpenClawExtendedCategory): OpenClawExtendedCapability[] {
  return OPENCLAW_EXTENDED.filter(c => c.category === category);
}

/**
 * Return all extended capabilities that are stubs or missing (i.e., implementation gaps).
 */
export function getExtendedGaps(): OpenClawExtendedCapability[] {
  return OPENCLAW_EXTENDED.filter(c => c.status === "stub" || c.status === "missing");
}
